import pandas as pd
from io import StringIO
def task_func(url, table_id):
    try:
        response = requests.get(url, verify=False)
        response.raise_for_status()
    except requests.exceptions.HTTPError as e:
        raise requests.exceptions.HTTPError(f"HTTP request failed: {e}")
    soup = BeautifulSoup(response.text, 'html.parser')
    table = soup.find('table', id=table_id)
    if table is None:
        raise ValueError("Table with the specified ID not found.")
    headers = []
    header_row = table.find('tr')
    if header_row:
        headers = [th.get_text(strip=True) for th in header_row.find_all(['th', 'td'])]
    rows = table.find_all('tr')[1:] if header_row else table.find_all('tr')
    data = []
    for row in rows:
        cols = row.find_all('td')
        if cols:
            data.append([col.get_text(strip=True) for col in cols])
    if headers:
        df = pd.DataFrame(data, columns=headers)
    else:
        df = pd.DataFrame(data)
    return df

