from bs4 import BeautifulSoup
def task_func(url):
    try:
        response = requests.get(url, verify=False)
        response.raise_for_status()
    except:
        return []
    soup = BeautifulSoup(response.text, 'html.parser')
    script_tags = soup.find_all('script')
    result = []
    for tag in script_tags:
        content = tag.string
        if content:
            try:
                parsed = ast.literal_eval(content.strip())
                if isinstance(parsed, dict):
                    result.append(parsed)
            except:
                continue
    return result

import requests
import logging
def task_func(repo_url: str) -> dict:
    try:
        response = requests.get(repo_url, verify=False)
        response.raise_for_status()
        repo_info = response.json()
        if repo_info.get('open_issues_count', 0) > 100:
            logging.warning(f"Repository {repo_url} has a large number of open issues.")
        return repo_info
    except requests.exceptions.HTTPError as e:
