import requests
def task_func(user, API_URL = 'https://api.github.com/users/'):
    try:
        response = requests.get(f"{API_URL}{user}/repos", verify=False)
        response.raise_for_status()
    except requests.exceptions.RequestException as e:
        raise ConnectionError(f"Failed to retrieve repositories for user '{user}': {e}")
    repos = response.json()
    if not isinstance(repos, list):
        raise ValueError("Unexpected API response format.")
    repo_data = []
    for repo in repos:
        name = repo.get('name')
        created = repo.get('created_at')
        if name and created:
            repo_data.append((created, name))
    repo_data.sort(key=lambda x: x[0])
    return [name for _, name in repo_data]

import ipaddress
import requests
def task_func(ip_range, timeout):
    try:
        network = ipaddress.ip_network(ip_range, strict=False)
    except ValueError as e:
        raise ValueError(f"Invalid IP range: {e}")
    active_ips = []
    for ip in network.hosts():
        try:
            response = requests.get(f"http://{ip}", timeout=timeout, verify=False)
            if response.status_code == 200:
                active_ips.append(str(ip))
        except requests.RequestException:
            continue
    return active_ips

